/**
 * Shared test helpers: a real UI configuration and a render function that wraps a
 * component in the same providers the app uses.
 *
 * `fixtures/config.json` is generated by `.tests/ui-fixture/generate.py` from the
 * configuration in that directory, so it is exactly what the UI build receives in
 * `hyperglass.json`. It has two location groups and three devices: Juniper and
 * Arista in "North America", and FRR in "Europe" with a select-type custom
 * directive (`peer_communities`). Regenerate it when the UI parameters change.
 */
import { ChakraProvider } from '@chakra-ui/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render } from '@testing-library/react';
import { HyperglassContext } from '~/context';
import { makeTheme } from '~/util';
import fixture from './fixtures/config.json';

import type { RenderOptions, RenderResult } from '@testing-library/react';
import type { PartialDeep } from 'type-fest';
import type { Config } from '~/types';

/** The generated UI configuration. Treat it as read-only; use `makeConfig` to vary it. */
export const testConfig = fixture as unknown as Config;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function merge<T>(base: T, overrides: unknown): T {
  if (!isPlainObject(base) || !isPlainObject(overrides)) {
    return (overrides === undefined ? base : overrides) as T;
  }
  const result: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(overrides)) {
    result[key] = merge(result[key], value);
  }
  return result as T;
}

/**
 * A copy of the test configuration with `overrides` merged in. Objects merge
 * recursively; arrays and other values replace the original.
 *
 * @example
 * ```ts
 * makeConfig({ web: { text: { submitButton: 'Go' } } });
 * ```
 */
export function makeConfig(overrides: PartialDeep<Config> = {}): Config {
  return merge(structuredClone(testConfig), overrides);
}

/** A React Query client for one test: no retries, so a failed request fails at once. */
export function makeQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
  });
}

interface ProviderOptions extends Omit<RenderOptions, 'wrapper'> {
  /** Configuration given to `useConfig()`. Defaults to `testConfig`. */
  config?: Config;
  /** React Query client. Defaults to a new client per render. */
  queryClient?: QueryClient;
}

interface ProviderResult extends RenderResult {
  config: Config;
  queryClient: QueryClient;
}

/**
 * Render `ui` inside the configuration context, Chakra UI with the configured theme,
 * and React Query, as `HyperglassProvider` does in the app. Unlike the app, each
 * render gets its own query client, so cached queries never leak between tests.
 */
export function renderWithProviders(
  ui: React.ReactElement,
  options: ProviderOptions = {},
): ProviderResult {
  const { config = testConfig, queryClient = makeQueryClient(), ...renderOptions } = options;
  const theme = makeTheme(config.web.theme, config.web.theme.defaultColorMode);
  const Wrapper = ({ children }: { children: React.ReactNode }): JSX.Element => (
    <HyperglassContext.Provider value={config}>
      <ChakraProvider theme={theme}>
        <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
      </ChakraProvider>
    </HyperglassContext.Provider>
  );
  return { ...render(ui, { wrapper: Wrapper, ...renderOptions }), config, queryClient };
}
